import React from 'react'
import { useDataLayerValue } from '../DataLayer'
import content from '../content';



function Profile() {

    const [{page},dispatch] = useDataLayerValue();

    const mainPage = () => {
        dispatch({
          type: "SET_PAGE",
          page: "main",
        });
      }


    return (
        <div>
            <img className={"absolute mx-4 my-2 opacity-40 hover:opacity-100"} onClick={mainPage} src={content.back}></img>
            <div className={"w-screen h-screen flex flex-wrap place-content-center"}>
                <div className={"w-48 h-48 bg-yellow-400 flex flex-wrap place-content-center z-0 hover:z-30"} >
                    <h1 className={"text-2xl"}>About</h1>
                </div>
                <div className={"w-48 h-48 bg-yellow-500 z-10"} >
                    <img className={"object-contain transform scale-125"} src={content.keenanColor} ></img>
                </div>
                <div className={"w-48 h-48 bg-yellow-600 flex flex-wrap place-content-center z-0 hover:z-30"} >
                    <h1 className={"text-2xl"}>Contact</h1>
                </div>
                <div className={"w-screen h-48 bg-yellow-700 flex flex-wrap place-content-center mt-10"}>
                    <div className={"h-48 w-1/3 bg-yellow-900"} >
                        <p>{content.bio}</p>
                    </div>
                </div>
            </div>

        </div>
    )
}

export default Profile
